import inspect

class FunctionWithSource:
    """
    Wrapper class that makes functions callable while adding methods to display:
    - .show() - Source code
    - .help() - Parameters and docstring
    - .params() - Quick parameter reference
    """
    def __init__(self, func):
        self.func = func
        self.__name__ = func.__name__
        self.__doc__ = func.__doc__
        self.__wrapped__ = func
    
    def __call__(self, *args, **kwargs):
        """Make the wrapper callable - executes the original function"""
        return self.func(*args, **kwargs)
    
    def show(self):
        """Display the source code of the wrapped function"""
        try:
            source = inspect.getsource(self.func)
            output = "\n" + "=" * 80 + f"\nSOURCE CODE: {self.__name__}()\n" + "=" * 80 + "\n" + source + "=" * 80 + "\n"
            print(output)
            return source
        except Exception as e:
            error_msg = f"Error retrieving source: {str(e)}"
            print(error_msg)
            return error_msg
    
    def help(self):
        """Display function parameters, defaults, and docstring"""
        sig = inspect.signature(self.func)
        help_text = "\n" + "=" * 80 + f"\nFUNCTION: {self.__name__}{sig}\n" + "=" * 80 + "\n"
        
        if self.__doc__:
            help_text += self.__doc__
        else:
            help_text += "No documentation available"
        
        help_text += "\n" + "=" * 80 + "\n"
        print(help_text)
        return help_text
    
    def params(self):
        """Quick parameter reference"""
        sig = inspect.signature(self.func)
        param_text = f"\n{self.__name__}{sig}"
        print(param_text)
        return param_text
    
    def __repr__(self):
        return f"<FunctionWithSource: {self.__name__}>"
